"use client"


import { OptimizedImage } from "@/components/ui/optimized-image"
import { AnimatePresence, motion } from "framer-motion"
import { Minus, Plus, Trash2 } from "lucide-react"
import { useCartStore } from "@/store/cart-store"
import { useLanguageStore } from "@/store/language-store"
import { Button } from "@/components/ui/button"
import { Sheet, SheetContent, SheetHeader, SheetTitle, SheetFooter } from "@/components/ui/sheet"
import { useToast } from "@/components/ui/use-toast"
import { useRouter } from "next/navigation"
import { formatCurrency } from "@/lib/currency"
import { getMenuImageUrl } from "@/lib/api-client"
import type { TranslationKey } from "@/lib/translations"

export function CartSheet() {
  const { toast } = useToast()
  const { t } = useLanguageStore()
  const router = useRouter()
  const { items, isCartOpen, toggleCart, updateQuantity, removeFromCart } = useCartStore()

  const total = items.reduce((acc, cartItem) => acc + cartItem.item.price * cartItem.quantity, 0)

  const handlePlaceOrder = () => {
    if (items.length === 0) {
      toast({
        title: t("cartEmpty"),
        description: t("addItemsFromMenu"),
        variant: "destructive",
      })
      return
    }
    toggleCart()
  }

  return (
    <>
      <Sheet open={isCartOpen} onOpenChange={toggleCart}>
        <SheetContent className="w-full max-w-md flex flex-col surface p-0">
          <SheetHeader className="p-4 pb-2 surface-sub divider">
            <SheetTitle className="font-serif text-3xl">{t("yourOrder")}</SheetTitle>
          </SheetHeader>
          <motion.div 
            className="flex-grow overflow-y-auto p-4 space-y-2"
            layout
            transition={{ type: "spring", stiffness: 300, damping: 30 }}
          >
            {items.length === 0 ? (
              <div className="text-center muted pt-8 space-y-2">
                <p className="text-lg">{t("cartEmpty")}</p>
                <p className="text-sm">{t("addItemsFromMenu")}</p>
              </div>
            ) : (
              <AnimatePresence mode="popLayout">
                {items.map(({ item, quantity }) => {
                  const itemName = t(item.nameKey as TranslationKey) || item.name
                  return (
                    <motion.div
                      key={item.id}
                      layout
                      initial={{ opacity: 0, y: 20 }}
                      animate={{ opacity: 1, y: 0 }}
                      exit={{ opacity: 0, x: -50, transition: { duration: 0.2 } }}
                      className="flex items-center space-x-3 p-3 surface-sub rounded-2xl"
                    >
                      <div className="relative w-14 h-14 flex-shrink-0">
                        <OptimizedImage
                          src={getMenuImageUrl(item.image) || "/placeholder.svg"}
                          alt={itemName}
                          fill
                          className="object-contain rounded-xl"
                        />
                      </div>
                      <div className="flex-grow">
                        <h4 className="font-semibold">{itemName}</h4>
      <p className="text-sm font-medium" style={{ color: 'var(--theme-secondary)' }}>{formatCurrency(item.price)}</p>
                        <div className="inline-flex items-center mt-1 surface-sub rounded-full p-1 gap-2 w-auto">
                          <Button
                            size="icon"
                            variant="ghost"
                            className="h-7 w-7 rounded-full icon-btn"
                            onClick={() => updateQuantity(item.id, quantity - 1)}
                          >
                            <Minus className="h-3 w-3" />
                          </Button>
                          <span className="w-6 text-center font-semibold text-sm">{quantity}</span>
                          <Button
                            size="icon"
                            variant="ghost"
                            className="h-7 w-7 rounded-full icon-btn"
                            onClick={() => updateQuantity(item.id, quantity + 1)}
                          >
                            <Plus className="h-3 w-3" />
                          </Button>
                        </div>
                      </div>
                      <Button
                        size="icon"
                        variant="ghost"
                        className="text-gray-400 hover:text-red-500 hover:bg-red-50 rounded-full h-7 w-7"
                        onClick={() => removeFromCart(item)}
                      >
                        <Trash2 className="h-3 w-3" />
                      </Button>
                    </motion.div>
                  )
                })}
              </AnimatePresence>
            )}
          </motion.div>
          {items.length > 0 && (
            <SheetFooter className="p-4 surface-sub divider mt-auto">
              <div className="w-full space-y-3">
                <div className="flex justify-between font-bold text-2xl">
                  <span>{t("total")}</span>
        <span>{formatCurrency(total)}</span>
                </div>
                <Button
                  className="w-full font-bold text-lg py-4 rounded-2xl shadow-lg transition-all duration-300 hover:shadow-xl"
                  style={{ 
                    background: 'var(--theme-button)',
                    color: 'var(--theme-background)'
                  }}
                  onClick={handlePlaceOrder}
                >
                  {t("proceedToPayment")}
                </Button>
              </div>
            </SheetFooter>
          )}
        </SheetContent>
      </Sheet>
    </>
  )
}
